    /** The statement of a person on a sheet that is not stored (one rebuilt as it stood at the end of
     *  a date, its today that date): counting their claims among {@code sheetClaims}, by the rates,
     *  floor, late charge and cap of the sheet and the person's holds and retirement, as the live
     *  totals do; their due-total held to the cap less their cut total. */
    public static Stated statedOn(Sheet sheet, Person person, Long personId, List<Claim> sheetClaims,
            RateChain.Levels sheetRates, BigDecimal cutTotal) {
        Optional<Sheet> held = Optional.of(sheet);
        LocalDate today = sheet.getToday();
        Function<LocalDate, BigDecimal> floor = floorOf(held);
        LateCharge late = LateCharge.of(held);
        Function<Claim, RoundingMode> rounding = roundingOf(held, sheetClaims);
        Map<Claim, BigDecimal> counted = new LinkedHashMap<>();
        sheetClaims.stream()
                .filter(c -> c.getPersonId().equals(personId) && countsFor(c, person, today))
                .forEach(c -> counted.put(c, shownDueOf(c, person, sheetRates, floor, late, rounding)));
        BigDecimal dueTotal = dueTotalOf(List.copyOf(counted.keySet()), person, sheetRates, today, floor, late, rounding, List.of());
        return new Stated(counted, Sheet.capped(dueTotal, capLessCut(sheet.getCap(), cutTotal)));
    }

    /** The due a claim of a person shows on a sheet that is not stored (one rebuilt as it stood at
     *  the end of a date, its today that date), among {@code sheetClaims}, by the rates, floor and
     *  late charge of that sheet, as the live figures show it (null: n/a). */

    /** Take a statement of a person: record their due-total now, and bind each of their claims
     *  that counts (OPEN, PENDING or SETTLED, but no unbound open one within a hold, nor a deferred one) to its figure now; the others
     *  are left unbound. Taken as of a date ({@code asOf}, not null), the sheet as it stood at the end
     *  of that date stands in for it now (see {@link #statementAsOf}). */
    @Transactional
    public Statement statement(String sheetId, String user, long personId, LocalDate asOf) {
        if (asOf != null) {
            return statementAsOf(sheetId, user, personId, asOf);
        }
        Person person = people.findForUpdate(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate today = sheets.today(sheetId);
        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        List<Claim> counted = theirs.stream().filter(c -> counts(c, person, today)).toList();
        // the due-total as the person shows it: their parts of claims shared with them included
        RollupService.Figures shown = before.people().get(personId);
        BigDecimal dueTotal = shown != null ? shown.dueTotal() : Sheet.capped(dueTotalOf(counted, person, today),
                RollupService.capLessCut(sheets.cap(sheetId), rollup.cutTotals(sheetId).get(personId)));
        for (Claim c : theirs) {
            if (counts(c, person, today)) {
                // the statement binds the due as shown, late charge included (a bound one stays as it is)
                c.bind(shownDueOf(c, person));
            } else {
                c.unbind();
            }
        }
        claims.flush();
        return stated(sheetId, user, person, theirs, dueTotal, counted.size(), today, null, before);
    }

